package com.nigson.acceptance.notification;
import com.nigson.commerce.notification.*;
import com.nigson.shared.events.EventCodec;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
public class NotificationValuesTest {
    public static tools.jackson.databind.JsonNode template(){return EventCodec.JSON.valueToTree(Map.of("code","ORDER_PAID","revision",1,"locale","en-NG","channel","EMAIL","classification","TRANSACTIONAL","body","Order {{orderNumber}} paid","variablesSchema",Map.of("type","object","additionalProperties",false,"properties",Map.of("orderNumber",Map.of("type","string","maxLength",40)),"required",List.of("orderNumber")),"active",true));}
    @Test void flatAllowlistedTemplatesEscapeDataAndLiteralHtmlWithoutExecutingExpressions(){var template=TemplateValues.template(template(),1);assertThat(TemplateValues.render(template,Map.of("orderNumber","<b>&\"'"))).isEqualTo("Order &lt;b&gt;&amp;&quot;&#39; paid");assertThat(template.toString()).doesNotContain("paid");var wire=TemplateValues.wire(template);assertThat(wire.has("subject")).isFalse();assertThat(wire.has("providerTemplateId")).isFalse();assertThat(wire.has("reason")).isFalse();assertThatThrownBy(()->TemplateValues.render(template,Map.of("orderNumber","a\nb"))).hasMessage("NOTIFICATION_RULE_VIOLATION");}
    @Test void schemasAndPlaceholdersAreClosedAndFutureOrUnapprovedActiveModesFail(){
        for(String body:List.of("{{{orderNumber}}}","{{#each orderNumber}}","{{orderNumber.value}}","{{secret}}")){var value=(tools.jackson.databind.node.ObjectNode)template().deepCopy();value.put("body",body);assertThatThrownBy(()->TemplateValues.template(value,1)).isInstanceOf(RuntimeException.class);}
        var value=(tools.jackson.databind.node.ObjectNode)template().deepCopy();value.put("code","CART_RECOVERY");assertThatThrownBy(()->TemplateValues.template(value,1)).hasMessage("NOTIFICATION_RULE_VIOLATION");value.put("code","ORDER_PAID");value.put("channel","WHATSAPP");assertThatThrownBy(()->TemplateValues.template(value,1)).hasMessage("NOTIFICATION_RULE_VIOLATION");
        var malicious=(tools.jackson.databind.node.ObjectNode)template().deepCopy();((tools.jackson.databind.node.ObjectNode)malicious.get("variablesSchema")).put("$ref","https://external.invalid/schema");assertThatThrownBy(()->TemplateValues.template(malicious,1)).hasMessage("NOTIFICATION_RULE_VIOLATION");
    }
    @Test void deliveryWireAndTrackingUrlsCannotCarryArbitraryPayloads(){var input=EventCodec.JSON.valueToTree(Map.of("jobId",UUID.randomUUID(),"resourceId",UUID.randomUUID(),"state","UNKNOWN"));assertThat(NotificationValues.delivery(input).toString()).isEqualTo("Delivery[protected]");for(String state:List.of("DELIVERED","PAID","CREATED")){var value=(tools.jackson.databind.node.ObjectNode)input.deepCopy();value.put("state",state);assertThatThrownBy(()->NotificationValues.delivery(value)).hasMessage("VALIDATION_ERROR");}var extra=(tools.jackson.databind.node.ObjectNode)input.deepCopy();extra.put("payload","protected");assertThatThrownBy(()->NotificationValues.delivery(extra)).hasMessage("VALIDATION_ERROR");for(String url:List.of("http://example.invalid","https://user:pass@example.invalid","javascript:alert(1)"))assertThatThrownBy(()->NotificationValues.tracking(url)).isInstanceOf(RuntimeException.class);}
 @org.junit.jupiter.api.Test void productionMetricPolicyRegistersOnlyClosedOutcomeValues(){var registry=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();registry.config().meterFilter(new com.nigson.commerce.platform.MetricPolicy());registry.counter("nigson.notification.outcomes","state","SENT").increment();assertThat(registry.find("nigson.notification.outcomes").tag("state","SENT").counter().count()).isEqualTo(1);registry.counter("nigson.notification.outcomes","state","customer@example.invalid").increment();assertThat(registry.find("nigson.notification.outcomes").tag("state","customer@example.invalid").counter()).isNull();registry.counter("nigson.files.transfer","outcome","CLEAN").increment();assertThat(registry.find("nigson.files.transfer").tag("outcome","CLEAN").counter().count()).isEqualTo(1);}
}
